    let activePool: ProbePool
    try {
      activePool = getPool()
    } catch {
      return false
    }

    try {
      return await activePool.probeUseCache(msg)
    } catch {
      // Worker crash or IPC error: tear down the pool so the next probe starts
      // fresh.
      await tearDownPool()
      return false
    }
  }

